const creativeRelinkBefore=JagoProjectModel.relink;JagoProjectModel.relink=function(p,from,to){const ok=creativeRelinkBefore(p,from,to);if(ok)JagoCreativeModel.remap(p,{[from]:to});return ok;};
const creativePackageBefore=projectPackageProject;projectPackageProject=function(plan){const p=creativePackageBefore(plan);if(p.creative)p.creative.backups=p.creative.backups.map(b=>({...b,path:''}));return p;};
const creativeTemplateApplyBefore=userTemplateApply;userTemplateApply=async function(t,values){const layout=await creativeTemplateApplyBefore(t,values);if(t.kind==='brand-kit'){const assets=[...new Set(layout.layers.flatMap(l=>[l.assetId,l.fontAsset].filter(Boolean)))],fonts=assets.map(asset).filter(a=>a?.type==='font');state.creative.brands.push({id:id(),name:t.name,assets,colours:(t.colours||[]).slice(0,32).map(JagoCreativeModel.colour),heading:layout.layers[t.project.layout.layers.findIndex(l=>l.fontAsset===t.heading)]?.fontAsset||fonts[0]?.id||'',body:layout.layers[t.project.layout.layers.findIndex(l=>l.fontAsset===t.body)]?.fontAsset||fonts[1]?.id||fonts[0]?.id||''});mark();}return layout;};JagoLibrary.userTemplateApply=userTemplateApply;
const creativeBrowserDeliveryBefore=workflowBrowserDelivery;workflowBrowserDelivery=async function(p,fonts,files,cancel,t){files.push({name:'ATTRIBUTION.txt',blob:new Blob([creativeAttributions(p)],{type:'text/plain'})});return creativeBrowserDeliveryBefore(p,fonts,files,cancel,t);};
const creativeKitReadmeBefore=projectKitReadme;projectKitReadme=function(p,report){return creativeKitReadmeBefore(p,report)+'\n\n'+creativeAttributions(p);};
function creativeValidateShelf(s){if(!s||s.format!=='jago-library-shelf'||s.version!==1||!Array.isArray(s.templates)||!Array.isArray(s.brands)||s.templates.length+s.brands.length>20||new TextEncoder().encode(JSON.stringify(s)).length>20000000)throw Error('Unsupported or oversized portable shelf.');for(const t of s.templates)userTemplateValidate(t);for(const b of s.brands){userTemplateValidate(b);if(b.kind!=='brand-kit')throw Error('Unsupported brand kit in shelf.');}return s;}
function creativePortable(){dialog('<h2>Portable project shelf</h2><p>Collect this project’s originals, editable designs, reference boards, planning and source notes. Optionally bring associated saved templates and brand kits so they can be reused on another computer.</p><div class="creativeForm"><label><input id="creativeShelfTemplates" type="checkbox" checked> Include associated templates and brand kits</label><label><input id="creativeShelfFonts" type="checkbox"> Include imported font files I have permission to share</label><label><input id="creativeShelfMissing" type="checkbox"> Continue with unavailable originals clearly reported</label></div><p id="creativeShelfReview"></p><button id="creativeShelfStart" class="primary">Save portable shelf ZIP…</button>');const plan=JagoProjectModel.plan(state,'all');$('creativeShelfReview').textContent=plan.assets.length+' assets · '+state.creative.referenceBoards.length+' reference boards · '+state.creative.versions.length+' version groups · '+(plan.unavailable.length+plan.missing.length)+' unavailable items';$('creativeShelfStart').onclick=()=>{const include=$('creativeShelfTemplates').checked,fonts=$('creativeShelfFonts').checked,allow=$('creativeShelfMissing').checked,p=projectPackageProject(plan),project=projectHome().id;if((plan.unavailable.length||plan.missing.length)&&!allow)return notice('Restore unavailable originals or confirm an explicit report.');let stop=false;$('dialog').close();workflowTaskPanel.hidden=false;workflowRun('Portable project shelf',async t=>{const shelf={format:'jago-library-shelf',version:1,sourceProjectId:project,templates:[],brands:[]};if(include){const templates=await userTemplateList(),brands=await creativeBrandList();for(const [list,read,out]of [[templates,userTemplateRead,shelf.templates],[brands,creativeBrandRead,shelf.brands]])for(const item of list){if(stop)throw Error('Portable shelf stopped');if(!(item.references||[]).some(r=>r.project===project))continue;if(shelf.templates.length+shelf.brands.length>=20)throw Error('Select a smaller project shelf: up to 20 associated kits. Export extra kits separately.');const kit=await read(item.id);if(!fonts)for(const a of kit.project.assets)if(a.type==='font'&&!a.system){a.missing=true;a.url='data:application/octet-stream;base64,AA==';}out.push(kit);workflowProgress(t,'Collecting '+item.name);}}creativeValidateShelf(shelf);if(stop||project!==projectHome().id)throw Error('Portable shelf stopped before saving');const json=JSON.stringify(shelf);if(native){const result=await projectKitRequest('project-kit-export',{project:JSON.stringify(p),fonts,delivery:true,exports:[],shelf:json,taskId:t.id,progressTotal:p.assets.filter(a=>!a.system&&!a.missing).length});if(result.cancelled){t.stopped=true;return;}t.path=result.path;t.detail='Project and reusable shelf saved';if(project===projectHome().id){state.creative.backups.unshift({name:result.path.split(/[\\/]/).pop(),path:result.path,time:Date.now(),kind:'Portable project shelf'});state.creative.backups=state.creative.backups.slice(0,30);mark();}reviewRecordExport({id:crypto.randomUUID(),projectId:project,name:result.path.split(/[\\/]/).pop(),path:result.path,time:Date.now(),bytes:result.bytes||0,status:'Saved portable shelf',settings:{kind:'portable shelf',templates:include,fonts}});}else{await workflowBrowserDelivery(p,fonts,[{name:'Shelf.json',blob:new Blob([json],{type:'application/json'})}],()=>stop,t);t.detail='Portable shelf ZIP download requested';}},()=>{stop=true;if(native)managedPost({type:'project-kit-cancel'});}).catch(e=>notice(e.message));};}
const creativeBrowserOpenBefore=projectBrowserOpenKit;projectBrowserOpenKit=async function(file){const opened=await creativeBrowserOpenBefore(file),zip=await projectReadArchive(await file.arrayBuffer(),40000000,20000000);if(zip.names.includes('Shelf.json'))opened.shelf=creativeValidateShelf(JSON.parse(new TextDecoder().decode(await zip.read('Shelf.json'))));return opened;};
const creativeAcceptBefore=projectAcceptKit;projectAcceptKit=async function(m){let shelf;if(m.shelf)shelf=creativeValidateShelf(typeof m.shelf==='string'?JSON.parse(m.shelf):m.shelf);await creativeAcceptBefore(m);if(shelf){let done=0,failed=0;for(const [items,write]of [[shelf.templates,userTemplateWrite],[shelf.brands,creativeBrandWrite]])for(const original of items){try{const t=JSON.parse(JSON.stringify(original));t.id=crypto.randomUUID();t.references=(t.references||[]).map(r=>r.project===shelf.sourceProjectId?{project:projectHome().id,asset:m.mapping?.[r.asset]||r.asset}:r);await write(t);done++;}catch{failed++;}}notice('Project shelf opened · '+done+' reusable kits imported'+(failed?' · '+failed+' kits need separate import because shelf storage is full':'')+'.');}return m;};
Object.assign(JagoLibrary,{creativeToolkit,creativeBrief,creativeVersions,creativeBrands,creativeRights,creativeInspect,creativeSearchDialog,creativeRecipes,creativeProfiles,creativePreflight,creativeSafety,creativePortable,creativeBrandList,creativeBrandRead,creativeBrandWrite,creativeValidateShelf,packageProject:projectPackageDialog,acceptPackage:projectAcceptKit,readBrowserPackage:projectBrowserOpenKit});
JagoCreativeModel.normalise(state);if(workspace==='home')renderProjectHome();renderLibrary();
const creativeLayerDetailsBefore=renderLayerDetails;renderLayerDetails=function(){creativeLayerDetailsBefore();if(!state.creative?.brands?.length)return;const l=layer(),host=$('layerDetails'),section=document.createElement('section');section.className='section';section.innerHTML='<h3>Project brand colours & type</h3>';for(const brand of state.creative.brands){const heading=document.createElement('strong');heading.textContent=brand.name;section.append(heading);const palette=document.createElement('div');palette.className='creativePalette';for(const colour of brand.colours){const button=reviewButton(colour,()=>{checkpoint();if(l?.kind==='text')l.color=colour;else if(l?.kind==='shape'){if(l.noFill||l.shape==='line')l.stroke=colour;else l.fill=colour;}else if(!l){state.layout.background=colour;state.layout.transparent=false;}mark();renderProduction();});button.disabled=!!l&&!['text','shape'].includes(l.kind);button.title=l?'Apply to selected text or shape':'Apply to design background';button.style.background=colour;if([1,3,5].map(i=>parseInt(colour.slice(i,i+2),16)).reduce((n,v)=>n+v,0)>450){button.style.color='#27363a';button.style.textShadow='none';}palette.append(button);}section.append(palette);for(const [label,key]of [['Heading font',brand.heading],['Body font',brand.body]]){const a=asset(key);if(!a||a.missing)continue;const button=reviewButton(label,async()=>{if(l?.kind!=='text')return notice('Select a text layer first.');const family=await ensureFont(a);if(a.fontFailed)return notice('This font needs its original file.');checkpoint();l.fontAsset=a.id;l.font=family;mark();renderProduction();});section.append(button);}}host.append(section);};

const creativeConsolidateBefore=JagoWorkflowModel.consolidate;JagoWorkflowModel.consolidate=function(p,keys,preferred){const n=creativeConsolidateBefore(p,keys,preferred);JagoCreativeModel.remap(p,Object.fromEntries(keys.filter(k=>k!==preferred).map(k=>[k,preferred])));return n;};
function creativeVersionEdit(v){dialog('<h2>Edit version group</h2><div class="creativeForm"><label>Name<input id="creativeVersionName" value="'+esc(v.name)+'"></label></div><p>Removing a revision here leaves its Library asset intact.</p><div id="creativeVersionMembers" class="creativeRows"></div><button id="creativeVersionSave">Save group</button>');for(const k of v.assets){const label=document.createElement('label');label.className='creativeRow';const input=document.createElement('input');input.type='checkbox';input.checked=true;input.dataset.versionAsset=k;label.append(input,document.createTextNode(' '+(asset(k)?.name||'Unavailable revision')));$('creativeVersionMembers').append(label);}$('creativeVersionSave').onclick=()=>{const keys=[...$('creativeVersionMembers').querySelectorAll('input:checked')].map(i=>i.dataset.versionAsset);if(!keys.length)return notice('Keep at least one revision or remove the group.');v.name=$('creativeVersionName').value.trim().slice(0,200)||v.name;v.assets=keys;if(!keys.includes(v.preferred))v.preferred=keys[0];mark();creativeVersions();};}
